"""SSC distance/heights numeric illustrated DRAFT 150/120/50; dev SymPy 1.14.0."""
from illustrated_geometry_bank import *
bank=Bank(10,'১০ম অধ্যায়: দূরত্ব ও উচ্চতা',dict(MCQ=150,CQ=120,SQ=50))
bank.book='Proshnobook — সংকলন ও নিজস্ব চিত্রসহ দূরত্ব ও উচ্চতা অনুশীলনী'
rt=S.sqrt(3)
def fig(kind,H,d,**kw):return ('height-'+kind,dict(height=float(H),distance=float(d),**{k:float(v) if isinstance(v,(int,float,S.Basic)) and not isinstance(v,bool) else v for k,v in kw.items()}))
def source(pdf,num,board,text,options,key,value,why,figure,native=False):
 bank.source(pdf,num,board,text,options,key,value,why,figure,native)
 bank.audit[-1]['adaptation']+=' প্রয়োগের মডেল স্পষ্ট করতে সমতল ভূমি/লম্ব উচ্চতা বা ভূমিসংলগ্ন দৃষ্টিবিন্দুর প্রচলিত অনুমান গদ্যে লেখা হয়েছে; আলাদা শিক্ষক পর্যালোচনা বাকি।'
source(20,2,'cumilla',r'সমতল ভূমিতে সূর্যের উন্নতি কোণ $60^\circ$ হলে $6\sqrt3$ মিটার লম্ব একটি উল্লম্ব খুঁটির ছায়ার দৈর্ঘ্য কত মিটার?', ['$9$','$6$',r'$3\sqrt3$',r'$2\sqrt3$'],'B',6,r'খুঁটির উচ্চতা/ছায়া $=\tan60^\circ=\sqrt3$। তাই ছায়া $=6\sqrt3/\sqrt3=6$ মিটার।',fig('single',6*rt,6))
source(49,10,'sylhet',r'একটি গাছের উচ্চতা $2\sqrt3$ মিটার। সমতল ভূমিতে গাছের গোড়া হতে 6 মিটার দূরের ভূমিসংলগ্ন বিন্দু থেকে শীর্ষের উন্নতি কোণ কত ডিগ্রি?', ['$15$','$30$','$45$','$60$'],'B',30,r'$\tan\theta=2\sqrt3/6=1/\sqrt3$। উন্নতি কোণ সূক্ষ্মকোণ, তাই $\theta=30^\circ$।',fig('single',2*rt,6))
source(67,24,'dinajpur',r'সমতল ভূমিতে সূর্যের উন্নতি কোণ $30^\circ$ হলে একটি উল্লম্ব দণ্ডের ছায়ার দৈর্ঘ্য তার উচ্চতার কত গুণ?', [r'$\frac1{\sqrt3}$',r'$\frac1{\sqrt2}$',r'$\sqrt2$',r'$\sqrt3$'],'D',rt,r'উচ্চতা/ছায়া $=\tan30^\circ=1/\sqrt3$। তাই ছায়া/উচ্চতা $=\sqrt3$।',fig('single',1,rt))
source(29,24,'jashore',r'সমতল ভূমিতে 20 মিটার লম্ব মই ভূমির সঙ্গে $30^\circ$ কোণ করে একটি উল্লম্ব দেয়াল স্পর্শ করে। দেয়ালে স্পর্শবিন্দুর উচ্চতা কত মিটার?', ['$10$','$12$','$20$','$40$'],'A',10,r'মই অতিভুজ। উচ্চতা $=20\sin30^\circ=20/2=10$ মিটার।',fig('single',10,10*rt))
source(58,8,'barishal',r'12 মিটার দীর্ঘ একটি মই দেয়াল থেকে $6\sqrt3$ মিটার দূরে সমতল ভূমির সঙ্গে θ কোণ উৎপন্ন করে উল্লম্ব দেয়ালে ঠেকানো আছে। θ কত ডিগ্রি?', ['$30$','$45$','$60$','$90$'],'A',30,r'$\cos\theta=6\sqrt3/12=\sqrt3/2$। ভূমির সঙ্গে মইয়ের সূক্ষ্মকোণ $30^\circ$।',fig('single',6,6*rt))
source(39,28,'chattogram',r'চিত্রে A,C,B একই উল্লম্ব রেখায়, BD অনুভূমিক; $BC=10$ মিটার, $\angle DCB=60^\circ$ এবং AC=CD। AB কত মিটার?', ['$20$',r'$10\sqrt2$','$30$',r'$30\sqrt2$'],'C',30,r'CDB সমকোণী। $\cos60^\circ=BC/CD=10/CD$ থেকে CD=20 মিটার। AC=CD=20, তাই AB=AC+CB=30 মিটার। এখানে ৬০° কোণটি উল্লম্ব CB-এর সঙ্গে, ভূমির সঙ্গে নয়।',fig('broken',10,10*rt,total=30),True)

assumption='উল্লম্ব বস্তু ও একই সমতল ভূমি ধরে, চোখের উচ্চতা উল্লেখ না থাকলে পর্যবেক্ষণবিন্দু ভূমিসংলগ্ন। '
def addmcq(f,n,text,value,why,figure):
 value=S.simplify(value);wrong=[]
 for v in [value/2,2*value,value+1,value+2,3*value,value-R(1,2)]:
  v=S.simplify(v)
  if v.is_positive and S.simplify(v-value)!=0 and all(S.simplify(v-w)!=0 for w in wrong):wrong.append(v)
  if len(wrong)==3:break
 bank.mcq(f,n,text,value,why,figure,wrong)
for n in range(1,13):
 k=S.Integer(n+4);e=R(3,2)
 rows=[
 ('tower-sixty',rf'সমতল ভূমিতে মিনারের পাদবিন্দু থেকে {k} মিটার দূরের ভূমিসংলগ্ন বিন্দুতে শীর্ষের উন্নতি কোণ $60^\circ$। মিনারের উচ্চতা কত মিটার?',k*rt,rf'$H={k}\tan60^\circ={tex(k*rt)}$ মিটার।',fig('single',k*rt,k)),
 ('distance-thirty',rf'{k} মিটার উঁচু উল্লম্ব মিনারের শীর্ষ ভূমিসংলগ্ন P থেকে $30^\circ$ উন্নতি কোণে দেখা যায়। সমতল ভূমিতে পাদবিন্দু থেকে P-এর দূরত্ব কত মিটার?',k*rt,rf'$d={k}/\tan30^\circ={tex(k*rt)}$ মিটার।',fig('single',k,k*rt)),
 ('ladder-thirty',rf'{2*k} মিটার লম্ব মই সমতল ভূমির সঙ্গে $30^\circ$ কোণ করে উল্লম্ব দেয়ালে ঠেকানো। স্পর্শবিন্দুর উচ্চতা কত মিটার?',k,rf'মই অতিভুজ; $H={2*k}\sin30^\circ={k}$ মিটার।',fig('single',k,k*rt)),
 ('ladder-sixty-base',rf'{2*k} মিটার লম্ব মই উল্লম্ব দেয়ালে ঠেকানো এবং সমতল ভূমির সঙ্গে $60^\circ$ কোণ করে। মইয়ের গোড়া দেয়াল থেকে কত মিটার দূরে?',k,rf'$d={2*k}\cos60^\circ={k}$ মিটার।',fig('single',k*rt,k)),
 ('equal-shadow',rf'সমতল ভূমিতে {k} মিটার উঁচু খুঁটির ছায়াও {k} মিটার। সূর্যের উন্নতি কোণ কত ডিগ্রি?',45,r'উচ্চতা/ছায়া =১, তাই tanθ=১; সূক্ষ্ম উন্নতি কোণ ৪৫°।',fig('single',k,k)),
 ('shadow-thirty',rf'{k} মিটার উঁচু উল্লম্ব দণ্ড সমতল ভূমিতে আছে। সূর্যের উন্নতি কোণ $30^\circ$ হলে ছায়ার দৈর্ঘ্য কত মিটার?',k*rt,rf'ছায়া $={k}\cot30^\circ={tex(k*rt)}$ মিটার।',fig('single',k,k*rt)),
 ('eye-height',rf'একই সমতল ভূমিতে দাঁড়ানো পর্যবেক্ষকের চোখের উচ্চতা 1.5 মিটার। {k} মিটার দূরের উল্লম্ব স্তম্ভের শীর্ষের উন্নতি কোণ $45^\circ$। স্তম্ভের মোট উচ্চতা কত মিটার?',k+e,rf'চোখের উপরকার অংশ $={k}\tan45^\circ={k}$। মোট উচ্চতা ${k}+1.5={tex(k+e)}$ মিটার।',fig('eye',k+e,k,eye=e)),
 ('depression-thirty',rf'সমতল জলপৃষ্ঠের উপর {k} মিটার উঁচু বাতিঘরের শীর্ষ থেকে একটি নৌকার অবনতি কোণ $30^\circ$। নৌকা থেকে বাতিঘরের পাদবিন্দুর অনুভূমিক দূরত্ব কত মিটার?',k*rt,rf'সমান্তরাল অনুভূমিকের কারণে নৌকা থেকে উন্নতি কোণও ৩০°। দূরত্ব $={k}\cot30^\circ={tex(k*rt)}$ মিটার।',fig('single',k,k*rt,depression=True)),
 ('same-side',rf'একই সমতল ভূমিতে মিনারের একই পাশে পাদবিন্দুগামী সরলরেখায় P নিকট ও Q দূর বিন্দু; PQ={2*k} মিটার। ভূমিসংলগ্ন P,Q থেকে শীর্ষের উন্নতি কোণ যথাক্রমে $60^\circ,30^\circ$। উচ্চতা কত মিটার?',k*rt,rf'নিকট দূরত্ব x হলে $H=x\sqrt3=(x+{2*k})/\sqrt3$। তাই $3x=x+{2*k}$, x={k}; $H={tex(k*rt)}$ মিটার।',fig('same',k*rt,k,far=3*k)),
 ('opposite-sides',rf'মিনারের পাদবিন্দু B, একই সমতল ভূমির P ও Q-এর মাঝে। P,B,Q সমরেখ, PQ={4*k} মিটার। ভূমিসংলগ্ন P,Q থেকে শীর্ষের উন্নতি কোণ যথাক্রমে $60^\circ,30^\circ$। উচ্চতা কত মিটার?',k*rt,rf'$PB=H/\sqrt3$, $BQ=H\sqrt3$। যোগ {4*k}; তাই $4H/\sqrt3={4*k}$ ও $H={tex(k*rt)}$।',fig('opposite',k*rt,3*k,left=k)),
 ('two-towers',rf'একই সমতল ভূমির দুটি উল্লম্ব স্তম্ভের ছোটটির উচ্চতা {k+2} মিটার এবং পাদবিন্দুদ্বয়ের দূরত্ব {2*k} মিটার। ছোটটির শীর্ষ থেকে বড়টির শীর্ষের উন্নতি কোণ $45^\circ$। বড়টির উচ্চতা কত মিটার?',3*k+2,rf'উচ্চতার পার্থক্য $={2*k}\tan45^\circ={2*k}$। বড়টির উচ্চতা ${k+2}+{2*k}={3*k+2}$ মিটার।',fig('towers',3*k+2,2*k,eye=k+2,depression=True)),
 ('broken-tree',rf'একটি গাছ ভেঙে তার অগ্রভাগ সমতল ভূমি স্পর্শ করে এবং ভাঙা অংশ ভূমির সঙ্গে $30^\circ$ কোণ করে। অবশিষ্ট উল্লম্ব অংশ {k} মিটার। গাছটির পূর্বের মোট উচ্চতা কত মিটার?',3*k,rf'ভাঙা অংশ অতিভুজ $L={k}/\sin30^\circ={2*k}$। পূর্বের উচ্চতা $H={k}+{2*k}={3*k}$ মিটার।',fig('broken',k,k*rt,total=3*k))]
 for f,text,v,why,figure in rows:addmcq(f,n,text,v,why,figure)

def cases(n):
 k=S.Integer(n+4);e=R(3,2);rows=[]
 def add(f,text,a,b,c,figure,checks):rows.append((f,text+' '+assumption,a,b,c,figure,checks))
 add('tower-sixty',rf'একটি মিনারের পাদবিন্দু B থেকে P-এর দূরত্ব {k} মিটার। P থেকে শীর্ষ T-এর উন্নতি কোণ $60^\circ$।',('সমকোণী ত্রিভুজের বাহুগুলো শনাক্ত কর।','BT উল্লম্ব উচ্চতা, BP অনুভূমিক দূরত্ব এবং PT দৃষ্টিরেখা; B-তে সমকোণ।'),('মিনারের উচ্চতা নির্ণয় কর।',rf'$BT/BP=\tan60^\circ=\sqrt3$; তাই $BT={tex(k*rt)}$ মিটার।'),('দৃষ্টিরেখা PT নির্ণয় ও পিথাগোরাসে যাচাই কর।',rf'$PT=BP/\cos60^\circ={2*k}$ মিটার। $BP^2+BT^2={k*k}+{3*k*k}={4*k*k}=PT^2$।'),fig('single',k*rt,k),[(k*rt/k,rt),(k*k+(k*rt)**2,(2*k)**2)])
 add('tower-thirty',rf'{k} মিটার উঁচু মিনারের শীর্ষ T, ভূমির P বিন্দু থেকে $30^\circ$ উন্নতি কোণে দেখা যায়। B মিনারের পাদবিন্দু।',('উচ্চতা ও অনুভূমিক দূরত্বের অনুপাত লেখ।',r'$BT/BP=\tan30^\circ=1/\sqrt3$।'),('BP ও PT নির্ণয় কর।',rf'$BP=BT\cot30^\circ={tex(k*rt)}$, $PT=BT/\sin30^\circ={2*k}$ মিটার।'),('P থেকে B-এর দিকে BP-এর দুই-তৃতীয়াংশ অগ্রসর হলে নতুন উন্নতি কোণ কত?',rf'নতুন দূরত্ব $BP/3={tex(k/rt)}$। তখন tanα=$BT/(BP/3)=\sqrt3$; তাই α=৬০°। চোখের উচ্চতা এই মডেলে শূন্য ধরা।'),fig('single',k,k*rt),[(k/(k*rt),1/rt),(k/(k*rt/3),rt)])
 add('ladder',rf'{2*k} মিটার লম্ব মই উল্লম্ব দেয়ালে সমতল ভূমির সঙ্গে $30^\circ$ কোণ করে ঠেকানো।',('এখানে অতিভুজ কোনটি এবং কেন?','মই অতিভুজ; দেয়াল ও সমতল ভূমি পরস্পর লম্ব।'),('মইয়ের শীর্ষের উচ্চতা ও গোড়ার দূরত্ব নির্ণয় কর।',rf'$H={2*k}\sin30^\circ={k}$; $d={2*k}\cos30^\circ={tex(k*rt)}$ মিটার।'),('একই মই ভূমির সঙ্গে ৪৫° কোণ করলে গোড়াকে দেয়ালের দিকে কত সরাতে হবে?',rf'নতুন দূরত্ব $d_2={2*k}\cos45^\circ={tex(k*S.sqrt(2))}$। সরাতে হবে $d-d_2={tex(k*(rt-S.sqrt(2)))}$ মিটার; √৩>√২ বলে পরিমাণ ধনাত্মক। মইয়ের দৈর্ঘ্য অপরিবর্তিত।'),fig('single',k,k*rt),[(k*k+(k*rt)**2,(2*k)**2),(k*rt-k*S.sqrt(2),k*(rt-S.sqrt(2)))])
 add('kite',rf'একটি ঘুড়ির টানটান সরল সুতা {2*k} মিটার; ভূমিসংলগ্ন হাতে সুতা ভূমির সঙ্গে $60^\circ$ কোণ করে। ঘুড়ির লম্ব পাদবিন্দু B, হাতের অবস্থান P। বাতাসে সুতার বাঁক উপেক্ষিত।',('সুতার দৈর্ঘ্য কী ধরনের বাহু?','দৃষ্টিরেখা/টানটান সুতা অতিভুজ; উল্লম্ব উচ্চতা ও অনুভূমিক দূরত্ব লম্ব বাহু।'),('ঘুড়ির উচ্চতা ও BP নির্ণয় কর।',rf'$H={2*k}\sin60^\circ={tex(k*rt)}$, $BP={2*k}\cos60^\circ={k}$ মিটার।'),('একই ৬০° কোণ রেখে সুতার দৈর্ঘ্য ৫০% বাড়ালে উচ্চতা কত বাড়বে?',rf'নতুন সুতা {3*k} মিটার, নতুন উচ্চতা ${tex(R(3,2)*k*rt)}$। বৃদ্ধি ${tex(k*rt/2)}$ মিটার। কোণ স্থির বলে sin অনুপাত স্থির; উচ্চতাও ৫০% বাড়ে।'),fig('single',k*rt,k),[(k*rt/(2*k),rt/2),(3*k*rt/2-k*rt,k*rt/2)])
 add('shadow-fortyfive',rf'সূর্যের উন্নতি কোণ $45^\circ$ হলে একটি উল্লম্ব খুঁটির ছায়ার দৈর্ঘ্য {k} মিটার।',('ছায়া ও উচ্চতার মধ্যে tan সম্পর্ক লেখ।',r'$\tan\theta=H/s$, যেখানে s অনুভূমিক ছায়ার দৈর্ঘ্য।'),('খুঁটির উচ্চতা নির্ণয় কর।',rf'$H={k}\tan45^\circ={k}$ মিটার।'),('পরে সূর্যের উন্নতি কোণ ৬০° হলে ছায়া কত কমবে?',rf'নতুন ছায়া $s_2=H\cot60^\circ={tex(k/rt)}$। হ্রাস ${tex(k-k/rt)}$ মিটার। একই উল্লম্ব খুঁটির উচ্চতা অপরিবর্তিত; সূর্যরশ্মি সরল ও ভূমি সমতল ধরা।'),fig('single',k,k),[(k*1,k),(k-k/rt,k*(1-1/rt))])
 add('shadow-thirty',rf'একটি উল্লম্ব খুঁটির উচ্চতা ${tex(k*rt)}$ মিটার। প্রথমে সূর্যের উন্নতি কোণ $30^\circ$, পরে $60^\circ$।',('কোন অবস্থায় ছায়া বেশি হবে? কেন?','৩০°-এ বেশি; নির্দিষ্ট উচ্চতায় ছায়া H/tanθ, এবং tan৩০°<tan৬০°।'),('দুই অবস্থায় ছায়ার দৈর্ঘ্য নির্ণয় কর।',rf'$s_1=H\cot30^\circ={3*k}$; $s_2=H\cot60^\circ={k}$ মিটার।'),('ছায়ার অনুপাত ও দৈর্ঘ্যের হ্রাস নির্ণয় কর।',rf'$s_1:s_2={3*k}:{k}=3:1$। হ্রাস $s_1-s_2={2*k}$ মিটার। কোণের অনুপাত ১:২ থেকে সরাসরি ছায়ার অনুপাত নেওয়া যায় না; tan ব্যবহার জরুরি।'),fig('single',k*rt,3*k),[(k*rt*rt,3*k),(3*k-k,2*k)])
 add('eye-level',rf'একই সমতলে দাঁড়ানো পর্যবেক্ষকের চোখ E ভূমি থেকে 1.5 মিটার উঁচু; স্তম্ভের পাদবিন্দু B থেকে পর্যবেক্ষকের পায়ের অবস্থান P-এর দূরত্ব {k} মিটার। শীর্ষ T-এর উন্নতি কোণ $45^\circ$।',('চোখের সমতলের উপরের উচ্চতার সমীকরণ লেখ।',rf'চোখের সমান্তরাল অনুভূমিক স্তম্ভকে M-এ ছেদ করলে EM=BP={k}, BM=EP=1.5; $\tan45^\circ=MT/EM$।'),('স্তম্ভের মোট উচ্চতা নির্ণয় কর।',rf'$MT={k}$; তাই $BT=BM+MT=1.5+{k}={tex(k+e)}$ মিটার।'),('চোখ থেকে শীর্ষের দৃষ্টিরেখা ET নির্ণয় এবং 1.5 বাদ দিলে ভুলের পরিমাণ লেখ।',rf'$ET=\sqrt{{EM^2+MT^2}}={tex(k*S.sqrt(2))}$ মিটার। চোখের উচ্চতা উপেক্ষা করে মোট উচ্চতা {k} বললে 1.5 মিটার কম হবে।'),fig('eye',k+e,k,eye=e),[(k+e-e,k),(k*k+k*k,(k*S.sqrt(2))**2)])
 add('boat-depression',rf'স্থির সমতল জলপৃষ্ঠের উপর বাতিঘরের শীর্ষ T-এর উচ্চতা {k} মিটার। প্রথমে একটি নৌকার অবনতি কোণ $30^\circ$, পরে নৌকা পাদবিন্দুর দিকে সরলরেখায় এগোলে $60^\circ$। নৌকাটিকে জলপৃষ্ঠের বিন্দু ধরা হয়েছে।',('অবনতি ও বিপরীত দিকের উন্নতি কোণ কেন সমান?', 'দুই স্থানের অনুভূমিক রেখা সমান্তরাল; দৃষ্টিরেখা ছেদক হওয়ায় একান্তর কোণ সমান।'),('বাতিঘর থেকে নৌকার দুই অনুভূমিক দূরত্ব নির্ণয় কর।',rf'$d_1={k}\cot30^\circ={tex(k*rt)}$; $d_2={k}\cot60^\circ={tex(k/rt)}$ মিটার।'),(rf'নৌকার বেগ ${tex(k/5)}$ মিটার/সেকেন্ড হলে এই অগ্রগতিতে সময় কত?',rf'অতিক্রান্ত দূরত্ব $d_1-d_2={tex(2*k/rt)}$ মিটার। সময় দূরত্ব/বেগ $=({tex(2*k/rt)})/({tex(k/5)})={tex(10/rt)}$ সেকেন্ড। এটি দৃষ্টিরেখার দৈর্ঘ্যের পরিবর্তন নয়।'),fig('single',k,k*rt,depression=True),[(k*rt-k/rt,2*k/rt),((k*rt-k/rt)/(k/5),10/rt)])
 add('same-side',rf'মিনারের একই পাশে B,P,Q সমরেখ, P নিকট ও Q দূর ভূমিসংলগ্ন বিন্দু। PQ={2*k} মিটার; P ও Q থেকে শীর্ষ T-এর উন্নতি কোণ যথাক্রমে $60^\circ$ ও $30^\circ$।',('BP=x ধরে দুই tan সমীকরণ লেখ।',rf'$H=x\sqrt3$ এবং $H=(x+{2*k})/\sqrt3$।'),('BP, BQ ও মিনারের উচ্চতা নির্ণয় কর।',rf'$3x=x+{2*k}$ থেকে x={k}; BQ={3*k}, $H={tex(k*rt)}$ মিটার।'),('দুই অবস্থানের দৃষ্টিরেখা PT ও QT নির্ণয় কর।',rf'$PT=BP/\cos60^\circ={2*k}$। $QT=BQ/\cos30^\circ={tex(2*k*rt)}$ মিটার। কাছের উন্নতি কোণ বড় হলেও দৃষ্টিরেখা ছোট; এটি দূরত্বের বিন্যাসের সঙ্গে সঙ্গত।'),fig('same',k*rt,k,far=3*k),[(3*k-k,2*k),((k*rt)**2+(3*k)**2,(2*k*rt)**2)])
 add('opposite-sides',rf'মিনারের পাদবিন্দু B, একই সমতলের P,Q বিন্দুর মাঝে এবং P,B,Q সমরেখ। PQ={4*k} মিটার; P থেকে T-এর উন্নতি কোণ $60^\circ$, Q থেকে $30^\circ$।',('H উচ্চতার মাধ্যমে PB ও BQ প্রকাশ কর।',r'$PB=H\cot60^\circ=H/\sqrt3$, $BQ=H\cot30^\circ=H\sqrt3$।'),('উচ্চতা ও দুই পাদবিন্দু-দূরত্ব নির্ণয় কর।',rf'$PB+BQ={4*k}$ থেকে $4H/\sqrt3={4*k}$। তাই $H={tex(k*rt)}$, PB={k}, BQ={3*k} মিটার।'),('ত্রিভুজ PTQ-এর ক্ষেত্রফল নির্ণয় কর এবং উচ্চতা কেন TB তা লেখ।',rf'PQ ভূমিতে এবং TB উল্লম্ব, তাই TB⊥PQ। ক্ষেত্রফল $=\frac12\times {4*k}\times {tex(k*rt)}={tex(2*k*k*rt)}$ বর্গমিটার। এখানে দূরত্বের যোগ নিতে হয়; একই-পাশের বিয়োগ নয়।'),fig('opposite',k*rt,3*k,left=k),[(k+3*k,4*k),(R(1,2)*4*k*k*rt,2*k*k*rt)])
 add('two-towers',rf'একই সমতলে দুটি উল্লম্ব স্তম্ভ BT ও DS; DS={k+2} মিটার, BD={2*k} মিটার। ছোটটির শীর্ষ S থেকে T-এর উন্নতি কোণ $45^\circ$।',('উচ্চতার পার্থক্যের সমীকরণ লেখ।',rf'$BT-DS=BD\tan45^\circ={2*k}$।'),('BT ও ST নির্ণয় কর।',rf'$BT={k+2}+{2*k}={3*k+2}$ মিটার। $ST=\sqrt{{{2*k}^2+{2*k}^2}}={tex(2*k*S.sqrt(2))}$ মিটার।'),('T থেকে S-এর অবনতি কোণ এবং D থেকে T-এর উন্নতি কোণের tan নির্ণয় কর।',rf'অবনতি কোণ উন্নতি কোণের সমান ৪৫°। কিন্তু D থেকে T-এর জন্য মোট BT নিতে হবে; $\tan\angle BDT=BT/BD={tex(R(3*k+2,2*k))}$। দুই দৃষ্টিবিন্দুর উচ্চতা আলাদা বলে কোণ এক নয়।'),fig('towers',3*k+2,2*k,eye=k+2,depression=True),[(3*k+2-(k+2),2*k),((2*k)**2+(2*k)**2,(2*k*S.sqrt(2))**2)])
 add('broken-tree',rf'একটি উল্লম্ব গাছ C-তে ভেঙে তার অগ্রভাগ D-তে সমতল ভূমি স্পর্শ করে। অবশিষ্ট BC={k} মিটার, ভাঙা অংশ CD ভূমি BD-এর সঙ্গে $30^\circ$ কোণ করে। A পূর্বের অগ্রবিন্দু, তাই AC=CD।',('মূল উচ্চতা AC+BC কেন, CD+BD নয়?', 'AC মূল গাছের ভাঙা উপরিভাগ, দৈর্ঘ্যে CD-এর সমান; BC অবশিষ্ট উল্লম্ব অংশ। BD মাটিতে অনুভূমিক বিস্তার, গাছের অংশ নয়।'),('ভাঙা অংশ CD ও ভূমিতে BD নির্ণয় কর।',rf'$CD=BC/\sin30^\circ={2*k}$। $BD=BC\cot30^\circ={tex(k*rt)}$ মিটার।'),('পূর্বের মোট উচ্চতা AB নির্ণয় ও ত্রিভুজের বাহুগুলো যাচাই কর।',rf'$AB=AC+BC=CD+BC={3*k}$ মিটার। পিথাগোরাসে $BC^2+BD^2={k*k}+{3*k*k}={4*k*k}=CD^2$; মডেলটি সঙ্গত।'),fig('broken',k,k*rt,total=3*k),[(k+2*k,3*k),(k*k+(k*rt)**2,(2*k)**2)])
 return rows
for n in range(1,11):
 for f,text,p1,p2,p3,figure,checks in cases(n):bank.written('CQ',f,n,text,[p1,p2,p3],figure,checks)
for n in range(1,6):
 for f,text,p1,p2,p3,figure,checks in cases(n)[:10]:bank.written('SQ',f,n,'সংক্ষিপ্ত প্রশ্ন: '+text+' '+p2[0],p2[1],figure,checks)
for q in bank.rows:
 if q['type']=='CQ':q['explanation']='চিত্র মাপানুযায়ী নয়। সমতল ভূমি/জলপৃষ্ঠ, উল্লম্ব বস্তু, দৃষ্টিবিন্দুর উচ্চতা ও নির্দিষ্ট অবস্থান ধরে ত্রিকোণমিতিক অনুপাত প্রয়োগ করা হয়েছে; সমাধান অংশগুলোতে দেওয়া আছে।'
bank.emit()
